import Foundation

/// One YouTube caption track for the current video, from the `/player` response's
/// `captions.playerCaptionsTracklistRenderer.captionTracks`. `url` is a signed, time-limited
/// timedtext URL already set to WebVTT — keep it in memory only (CLAUDE.md §2.6).
struct CaptionTrack: Identifiable, Hashable, Sendable {
    /// Language code plus `.asr` for auto-generated tracks (e.g. `en`, `en.asr`).
    let id: String
    /// Display name from YouTube, e.g. "English" / "English (auto-generated)".
    let name: String
    let languageCode: String
    let isAutoGenerated: Bool
    let url: URL
}
